import{_ as e,o as r,c as a,ag as o}from"./chunks/framework.CPvOxTBX.js";const g=JSON.parse('{"title":"翻译","description":"","frontmatter":{},"headers":[],"relativePath":"zh/guide/translation.md","filePath":"zh/guide/translation.md","lastUpdated":1793489430000}'),d={name:"zh/guide/translation.md"};function l(n,t,i,s,h,p){return r(),a("div",null,t[0]||(t[0]=[o('<h1 id="翻译" tabindex="-1">翻译 <a class="header-anchor" href="#翻译" aria-label="Permalink to &quot;翻译&quot;">​</a></h1><p>词悦的翻译页用于在不同语言之间翻译文本。与传统的单引擎翻译不同，它可以<strong>同时向多个源查询</strong>——免费网络服务、官方 API 和 AI 服务商——每个结果单独成卡展示，你可以把 Google、DeepL 和某个大模型对同一句话的翻译并排比较，挑最好的一个。</p><h2 id="使用翻译" tabindex="-1">使用翻译 <a class="header-anchor" href="#使用翻译" aria-label="Permalink to &quot;使用翻译&quot;">​</a></h2><ol><li>打开翻译页，输入或粘贴文本。</li><li>选择源语言和目标语言（源语言默认为自动检测），或点交换按钮互换两者。</li><li>点<strong>翻译</strong>。所有启用的源会被并行请求，结果按返回速度陆续填入卡片。桌面端可按 <code>Ctrl+Enter</code> 翻译。</li><li>每张卡片都有<strong>朗读</strong>和<strong>复制</strong>按钮。部分源（如 DeepL Free）还会返回备选译文，以 chip 形式显示在主结果下方，点一下即可复制。</li></ol><p>某个源失败只会影响它自己的卡片，不影响其他结果。</p><h2 id="管理翻译源" tabindex="-1">管理翻译源 <a class="header-anchor" href="#管理翻译源" aria-label="Permalink to &quot;管理翻译源&quot;">​</a></h2><p>从翻译页打开翻译设置，可以看到源列表：</p><ul><li><strong>开关</strong>：逐个启用/停用，至少保留一个启用。</li><li><strong>排序</strong>：按住拖动手柄调整顺序，结果卡片按同一顺序排列。</li><li><strong>配置</strong>：需要配置的源会显示「已配置 / 未配置」，展开后填写所需字段。</li><li>已启用但未配置的源在翻译时会被跳过，并在结果下方给出提示。</li></ul><p>升级后默认只启用你原来用的那个源，原有行为不变。</p><h2 id="免费源-无需-api-key" tabindex="-1">免费源（无需 API Key） <a class="header-anchor" href="#免费源-无需-api-key" aria-label="Permalink to &quot;免费源（无需 API Key）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>源</th><th>说明</th></tr></thead><tbody><tr><td>Google</td><td>Google 翻译的网页公开接口</td></tr><tr><td>Microsoft</td><td>Microsoft Edge 翻译接口</td></tr><tr><td>DeepL (Free)</td><td>DeepL 网页接口，可能返回多个备选译文</td></tr><tr><td>Baidu</td><td>百度翻译网页接口</td></tr><tr><td>Tencent</td><td>腾讯翻译君（TransMart）网页接口</td></tr><tr><td>Volcengine</td><td>火山翻译网页接口</td></tr><tr><td>Yandex (Free)</td><td>Yandex 翻译免费接口</td></tr></tbody></table><h2 id="官方-api-源-自备-api-key" tabindex="-1">官方 API 源（自备 API Key） <a class="header-anchor" href="#官方-api-源-自备-api-key" aria-label="Permalink to &quot;官方 API 源（自备 API Key）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>源</th><th>需要什么</th><th>申请入口</th></tr></thead><tbody><tr><td>DeepL</td><td>API Key（免费版 key 以 <code>:fx</code> 结尾，会自动使用免费端点）</td><td><a href="https://www.deepl.com/pro-api" target="_blank" rel="noreferrer">DeepL API</a></td></tr><tr><td>Google Cloud</td><td>Cloud Translation API Key</td><td><a href="https://console.cloud.google.com/apis/api/translate.googleapis.com" target="_blank" rel="noreferrer">Google Cloud 控制台</a></td></tr><tr><td>Azure</td><td>翻译资源 Key <strong>和</strong>资源所在区域</td><td><a href="https://portal.azure.com/#create/Microsoft.CognitiveServicesTextTranslation" target="_blank" rel="noreferrer">Azure 门户</a></td></tr><tr><td>Yandex Cloud</td><td>API Key <strong>和</strong>文件夹 ID</td><td><a href="https://console.cloud.yandex.com/" target="_blank" rel="noreferrer">Yandex Cloud 控制台</a></td></tr><tr><td>DeepLX</td><td>你自建的 DeepLX 实例 URL</td><td><a href="https://github.com/OwO-Network/DeepLX" target="_blank" rel="noreferrer">DeepLX</a></td></tr></tbody></table><h2 id="ai-服务商作为翻译源" tabindex="-1">AI 服务商作为翻译源 <a class="header-anchor" href="#ai-服务商作为翻译源" aria-label="Permalink to &quot;AI 服务商作为翻译源&quot;">​</a></h2><p>在<strong>设置 → AI</strong> 中配置过的每个 AI 服务商（OpenAI、Gemini、DeepSeek、Anthropic、OpenRouter、SiliconFlow、智谱、xAI、Ollama 等）也都是一个翻译源。判定「已配置」的标准是 AI 设置里填了模型和 API Key（Ollama 等本地服务不需要 Key）。你可以同时启用多个 AI 服务商，和机器翻译源放在一起对比效果。AI 的结果按 markdown 渲染，配合翻译设置里的富文本输出模式效果更好。</p><h2 id="免责声明" tabindex="-1">免责声明 <a class="header-anchor" href="#免责声明" aria-label="Permalink to &quot;免责声明&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">请仔细阅读</p><p>标注为<strong>免费</strong>的翻译源调用的是各服务商网页端或客户端的公开接口，<strong>并非</strong>服务商提供的官方开放 API。服务商可能随时变更、限制或终止这类接口，使用它们也可能不符合相应服务商的服务条款。本应用仅将它们作为可选项提供，是否启用由您自行决定，相关风险由您自行承担。</p><p>需要 API Key 的源使用您自行申请的凭据，产生的费用、配额与合规责任由您与服务商之间解决。</p><p>您输入的翻译文本会被直接发送至您所启用的<strong>每个</strong>翻译源的服务器，请勿翻译您不希望第三方处理的内容。词悦本身不收集、不上传您的翻译内容。</p></div><p>如果某个免费源突然不能用了，多半是服务商变更或封禁了接口，并不是词悦的 bug。请停用该源、改用其他源，或换成官方 API 源。</p>',18)]))}const u=e(d,[["render",l]]);export{g as __pageData,u as default};
